def get_pixtocam(
    focal_length, width, height, xnp = np
):
  """Returns the inverse intrinsic matrix for a pinhole camera."""
  intrinsic = xnp.block([
      [focal_length, 0, 0],
      [0, focal_length * height / width, 0],
      [0, 0, 1],
  ])
  return xnp.linalg.inv(intrinsic)


def get_spherical_pixtocam(
    width, height, xnp = np
):
  """Returns the inverse intrinsic matrix for a spherical camera."""
  return xnp.diag(xnp.array([2.0 * np.pi / width, np.pi / height, 1.0]))


