class StreamingDataLoaderReader(BaseReader):
    def __init__(self, streaming_data_loader: StreamingDataLoader):
        self.streaming_data_loader = streaming_data_loader
        self.current_idx = 0
        self.current_slice = None
        self.current_item = None

    def remap_items(self, user_items: List[Any], num_workers: int) -> List[List[Any]]:
        return _map_items_to_workers_sequentially(num_workers=num_workers, user_items=user_items)

    def read(self, slice: slice) -> Any:
        if self.current_slice != slice:
            self.current_slice = slice
            self.current_idx = 0
            self.current_item = None

        if self.current_idx >= len(self.streaming_data_loader):
            self.current_idx = 0
            self.current_item = None

        if self.current_item is None:
            self.current_item = self.streaming_data_loader[self.current_idx]
            self.current_idx += 1

        return self.current_item


