    def __init__(self, streaming_data_loader: StreamingDataLoader):
        self.streaming_data_loader = streaming_data_loader
        self.num_workers = _get_num_workers()
        self.node_rank = _get_node_rank()

    def remap_items(self, items: List[Any], weights: Optional[List[int]] = None) -> List[List[Any]]:
        """Map the items to workers.

        Arguments:
            items: The items to map to workers.
            weights: The weights associated to the items.

        """
        if weights is None:
            return _map_items_to_workers_sequentially(num_workers=self.num_workers, user_items=items)
        return _map_items_to_workers_weighted(num_workers=self.num_workers, user_items=items, weights=weights)

    def read(self, items: List[Any], weights: Optional[List[int]] = None) -> List[Any]:
        """Read the items from the streaming data loader."""
        if not isinstance(self.streaming_data_loader, StreamingDataLoader):
            raise ValueError("The provided value should be a streaming data loader.")

        workers_items = self.remap_items(items, weights)
        workers_data: List[Any] = []
        for worker_idx, worker_items in enumerate(workers_items):
            if worker_idx == self.node_rank:
                workers_data.append(self.streaming_data_loader.read(worker_items))
            else:
                workers_data.append(None)
        return workers_data


