class BaseReader(ABC):
    def __init__(self, items: List[Any]) -> None:
        self.items = items

    @abstractmethod
    def remap_items(self, items: List[Any], num_workers: int) -> List[List[Any]]:
        """Remap the items to worker items."""

    @abstractmethod
    def read(self, item_metadata: Any, is_last: bool) -> Any:
        """Read the item metadata."""


class StreamingDataLoaderReader(BaseReader):
    def __init__(self, items: List[Any]) -> None:
        self.items = items

    def remap_items(self, items: List[Any], num_workers: int) -> List[List[Any]]:
        """Remap the items to worker items."""
        return _map_items_to_workers_sequentially(num_workers=num_workers, user_items=items)

    def read(self, item_metadata: Any, is_last: bool) -> Any:
        """Read the item metadata."""
        return item_metadata


class StreamingDataLoader(StreamingDataLoaderReader):
    def __init__(self, items: List[Any]) -> None:
        self.items = items

    def __iter__(self) -> Any:
        """The `StreamingDataLoader` provides an efficient way to read data across multiple machine into chunks to
        make training faster.

        Arguments:
            items: The items to read.

        """
        for item in self.items:
            yield item


