def get_pixtocam(
    focal_length, width, height, xnp=np,
):
  """Gets a pixtocam matrix."""
  return xnp.block(
      [
          [focal_length, 0, 0, 0],
          [0, focal_length * height / width, 0, 0],
          [0, 0, 1, 0],
      ],
      [3, 3],
  )


def get_camtoworld(
    world_to_cam,
):
  """Gets a camtoworld matrix."""
  return world_to_cam[:3, :]


def get_cameras(
    intrinsics, extrinsics, distortion_params = None,
):
  """Gets a cameras tuple."""
  return (
      intrinsics,
      extrinsics,
      distortion_params,
  )


def get_pinhole_cameras(
    focal_length, width, height, xnp=np,
):
  """Gets a pinhole cameras tuple."""
  return get_cameras(
      get_pixtocam(focal_length, width, height, xnp=xnp),
      xnp.diag(xnp.array([2.0 * np.pi / width, np.pi / height, 1.0])),
      xnp,
  )


def get_spherical_cameras(
    width, height, xnp=np,
):
  """Gets a spherical cameras tuple."""
  return get_cameras(
