def get_blocks(doc_id):
    url = f"https://api.nlm.nih.gov/lit/ctx/v1/pubmed/{doc_id}/blocks"
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        return response.json()
    else:
        return None

def get_document_info(doc_id):
    url = f"https://api.nlm.nih.gov/lit/ctx/v1/pubmed/{doc_id}/document"
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        return response.json()
    else:
        return None

def get_document_info_from_file(doc_id):
