def score_query(self, query: str, similarity: Similarity = default_bm25) -> np.ndarray:
    """Score a query against the postings."""
    return self._score_field(query, similarity)

def score(self, term: str, similarity: Similarity = default_bm25) -> np.ndarray:
    """Score a term against the postings."""
    return self._score_field(term, similarity)

def _score_field(self, field: str, similarity: Similarity) -> np.ndarray:
    """Score a field against the postings."""
    if field not in self._field_index:
        return np.zeros(len(self._frame))

    postings = self._field_index[field]
    scores = np.zeros(len(self._frame))
    for doc_id, freq in postings:
        scores[doc_id] = similarity(self._frame, doc_id, field, freq)
    return scores

def explain(self, term: str) -> str:
    """Explain the score of a term against the postings."""
    if term not in self._term_index:
        return f"No match for {term}"

    postings = self._term_index[term]
    explain = []
    for doc_id, freq in postings:
        explain.append(f"{doc_id} ({freq})")
    return f"{term} -> " + " | ".join(explain)

def explain_query(self, query: str) -> str:
    """Explain the score of a query against the postings."""
    explain = []
    for term in self.tokenizer(query):
        explain.append(self.explain(term))

